func ptrCostEvent(p unsafe.Pointer, c int32) any {
	r := (*carriersettlement.CostEvent)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CarrierID))
	case 4:
		return (**string)(unsafe.Pointer(&r.CarrierAssignmentID))
	case 5:
		return (**string)(unsafe.Pointer(&r.ShipmentID))
	case 6:
		return (**string)(unsafe.Pointer(&r.MoveID))
	case 7:
		return (**string)(unsafe.Pointer(&r.SettlementID))
	case 8:
		return (*string)(unsafe.Pointer(&r.EventType))
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return &r.IdempotencyKey
	case 11:
		return &r.EventDate
	case 12:
		return &r.AmountMinor
	case 13:
		return &r.CurrencyCode
	case 14:
		return &r.Description
	case 15:
		return &r.ProNumber
	case 16:
		return &r.AssignmentVersion
	case 17:
		return &r.VoidedAt
	case 18:
		return &r.VoidReason
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	}
	return nil
}

func valueCostEvent(p unsafe.Pointer, c int32) any {
	r := (*carriersettlement.CostEvent)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.CarrierID)
	case 4:
		if r.CarrierAssignmentID == nil {
			return nil
		}
		return string(*r.CarrierAssignmentID)
	case 5:
		if r.ShipmentID == nil {
			return nil
		}
		return string(*r.ShipmentID)
	case 6:
		if r.MoveID == nil {
			return nil
		}
		return string(*r.MoveID)
	case 7:
		if r.SettlementID == nil {
			return nil
		}
		return string(*r.SettlementID)
	case 8:
		return string(r.EventType)
	case 9:
		return string(r.Status)
	case 10:
		return r.IdempotencyKey
	case 11:
		return r.EventDate
	case 12:
		return r.AmountMinor
	case 13:
		return r.CurrencyCode
	case 14:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 15:
		if r.ProNumber == "" {
			return nil
		}
		return r.ProNumber
	case 16:
		return r.AssignmentVersion
	case 17:
		if r.VoidedAt == nil {
			return nil
		}
		return *r.VoidedAt
	case 18:
		if r.VoidReason == "" {
			return nil
		}
		return r.VoidReason
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	}
	return nil
}

